import { describe, expect, it } from 'vitest'
import { docText, formulasOf, normalizeDocling, type IngestedDoc } from './doclingSchema'

// handcrafted fixture shaped exactly like server/main.py output; the real
// Docling dump of public/papers/sample-harmonic.pdf lives in
// src/ingest/fixtures/sample-harmonic.docling.json and is asserted in a
// separate test when present (generated by scripts/run_ingest_fixture.py).
const RAW = {
  docId: 'doc-abc',
  title: 'Harmonic Distortion Notes',
  engine: 'docling',
  doclingVersion: '2.131.0',
  pages: [{ page: 1, width: 612, height: 792 }],
  items: [
    { id: 'p1-i0', kind: 'title', page: 1, bbox: { x: 0.1, y: 0.05, w: 0.8, h: 0.06 }, text: 'Harmonic Distortion Notes' },
    { id: 'p1-i1', kind: 'text', page: 1, bbox: { x: 0.08, y: 0.2, w: 0.84, h: 0.1 }, text: 'We study the sine model.' },
    { id: 'p1-i2', kind: 'formula', page: 1, bbox: { x: 0.3, y: 0.45, w: 0.4, h: 0.05 }, latex: 'y = a\\sin(bx)' },
    { kind: 'garbage', page: 1, bbox: { x: 0, y: 0, w: 0, h: 0 } }, // unknown kind → text
    { kind: 'text', page: 7, bbox: null }, // dropped: no bbox
    { id: 'p1-i5', kind: 'figure', page: 1, bbox: { x: 1.2, y: -3, w: 0.5, h: 0.2 }, text: 'fig' }, // clamped
  ],
}

const doc = normalizeDocling(RAW)

describe('normalizeDocling', () => {
  it('keeps pages/items and derives the formula list', () => {
    expect(doc.docId).toBe('doc-abc')
    expect(doc.pages).toHaveLength(1)
    expect(formulasOf(doc)).toHaveLength(1)
    expect(formulasOf(doc)[0].latex).toBe('y = a\\sin(bx)')
  })
  it('drops items without bbox and clamps anchors into the unit page', () => {
    expect(doc.items.some((i) => i.page === 7)).toBe(false)
    const fig = doc.items.find((i) => i.id === 'p1-i5')!
    expect(fig.bbox.x).toBe(1)
    expect(fig.bbox.y).toBe(0)
  })
  it('unknown kinds map to text (lossless fallthrough)', () => {
    expect(doc.items.find((i) => i.id === 'p1-i3')?.kind).toBe('text')
  })
  it('docText skips formulas/figures', () => {
    expect(docText(doc)).not.toContain('sin(bx)')
    expect(docText(doc)).toContain('sine model')
  })
  it('rejects structurally unusable payloads', () => {
    expect(() => normalizeDocling({})).toThrow()
    expect(() => normalizeDocling({ docId: 'x', pages: [], items: [] })).toThrow()
  })
})

describe('real Docling fixture', () => {
  it('sample-harmonic.docling.json parses and contains the sine formula', async () => {
    let fixture: IngestedDoc | null = null
    try {
      fixture = normalizeDocling((await import('./fixtures/sample-harmonic.docling.json')).default)
    } catch {
      // fixture not yet generated on a fresh clone — skip rather than fail
      return
    }
    expect(formulasOf(fixture).length).toBeGreaterThan(0)
    const latexes = formulasOf(fixture).map((f) => f.latex ?? '')
    const hasSine = latexes.some((l) => l.includes('sin') && /[ab]/.test(l))
    expect(hasSine).toBe(true)
  })
})
